package com.demo.invoicedesk;

import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class GdtControlService {
 private static final ZoneId ZONE=ZoneId.of("Asia/Ho_Chi_Minh");
 private final JdbcTemplate db;
 public GdtControlService(JdbcTemplate db){this.db=db;}
 public record Policy(int trialDays,String invoiceQuotaMode,int monthlyRunLimit,int monthlyInvoiceLimit,int monthlyOcrLimit,int dailyOcrLimit,int maxInvoicesPerJob,int maxDevices,boolean localOcrEnabled,boolean onlineOcrEnabled,boolean suspended,Instant trialEndsAt){}
 public record Usage(Policy policy,int runUsed,int runRemaining,int invoiceUsed,int invoiceRemaining,int ocrUsed,int ocrRemaining,int ocrToday,int ocrTodayRemaining){}
 public record LoginGate(boolean allowed,int failures,Instant blockedUntil,String message){}
 public record Reservation(UUID reservationId,int requested,int newlyCharged,int alreadyCounted,int remaining){}
 public record Defaults(int trialDays,String invoiceQuotaMode,int monthlyRunLimit,int monthlyInvoiceLimit,int monthlyOcrLimit,int dailyOcrLimit,int maxInvoicesPerJob,int maxDevices,boolean localOcrEnabled,boolean onlineOcrEnabled,int telemetryRetentionDays){}

 private LocalDate month(){return LocalDate.now(ZONE).withDayOfMonth(1);}
 private LocalDate today(){return LocalDate.now(ZONE);}
 private void ensurePolicy(UUID tenant){db.update("""
  INSERT INTO invoice_desk_gdt_policy(tenant_id,trial_ends_at)
  SELECT ?,CURRENT_TIMESTAMP+(trial_days||' days')::interval FROM invoice_desk_gdt_defaults WHERE singleton=true
  ON CONFLICT(tenant_id) DO NOTHING
  """,tenant);}
 public Policy policy(UUID tenant){ensurePolicy(tenant);return db.queryForObject("""
  SELECT d.trial_days,COALESCE(p.invoice_quota_mode,d.invoice_quota_mode),COALESCE(p.monthly_run_limit,d.monthly_run_limit),COALESCE(p.monthly_invoice_limit,d.monthly_invoice_limit),COALESCE(p.monthly_ocr_limit,d.monthly_ocr_limit),
  COALESCE(p.daily_ocr_limit,d.daily_ocr_limit),COALESCE(p.max_invoices_per_job,d.max_invoices_per_job),COALESCE(p.max_devices,d.max_devices),
  COALESCE(p.local_ocr_enabled,d.local_ocr_enabled),COALESCE(p.online_ocr_enabled,d.online_ocr_enabled),p.suspended,p.trial_ends_at
  FROM invoice_desk_gdt_defaults d JOIN invoice_desk_gdt_policy p ON p.tenant_id=? WHERE d.singleton=true
  """,(rs,n)->{OffsetDateTime end=rs.getObject(12,OffsetDateTime.class);return new Policy(rs.getInt(1),rs.getString(2),rs.getInt(3),rs.getInt(4),rs.getInt(5),rs.getInt(6),rs.getInt(7),rs.getInt(8),rs.getBoolean(9),rs.getBoolean(10),rs.getBoolean(11),end==null?null:end.toInstant());},tenant);}
 private void active(Policy p){if(p.suspended())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"GDT service is suspended.");if(p.trialEndsAt()!=null&&Instant.now().isAfter(p.trialEndsAt()))throw new ResponseStatusException(HttpStatus.PAYMENT_REQUIRED,"GDT trial has expired.");}
 public Usage usage(UUID tenant){Policy p=policy(tenant);int[] monthly=db.query("SELECT report_runs,invoice_downloads,ocr_attempts FROM invoice_desk_gdt_usage WHERE tenant_id=? AND usage_month=?",(rs,n)->new int[]{rs.getInt(1),rs.getInt(2),rs.getInt(3)},tenant,month()).stream().findFirst().orElse(new int[3]);Integer daily=db.query("SELECT ocr_attempts FROM invoice_desk_gdt_daily_usage WHERE tenant_id=? AND usage_day=?",(rs,n)->rs.getInt(1),tenant,today()).stream().findFirst().orElse(0);return new Usage(p,monthly[0],Math.max(0,p.monthlyRunLimit()-monthly[0]),monthly[1],Math.max(0,p.monthlyInvoiceLimit()-monthly[1]),monthly[2],Math.max(0,p.monthlyOcrLimit()-monthly[2]),daily,Math.max(0,p.dailyOcrLimit()-daily));}

 @Transactional public Usage resetUsage(UUID tenant,boolean all,String actor){policy(tenant);LocalDate start=month(),end=start.plusMonths(1);int charges,runs,daily,monthly;if(all){charges=db.update("DELETE FROM invoice_desk_gdt_invoice_charge WHERE tenant_id=?",tenant);runs=db.update("DELETE FROM invoice_desk_gdt_run_reservation WHERE tenant_id=?",tenant);daily=db.update("DELETE FROM invoice_desk_gdt_daily_usage WHERE tenant_id=?",tenant);monthly=db.update("DELETE FROM invoice_desk_gdt_usage WHERE tenant_id=?",tenant);}else{charges=db.update("DELETE FROM invoice_desk_gdt_invoice_charge WHERE tenant_id=? AND charged_month=?",tenant,start);runs=db.update("DELETE FROM invoice_desk_gdt_run_reservation WHERE tenant_id=? AND charged_month=?",tenant,start);daily=db.update("DELETE FROM invoice_desk_gdt_daily_usage WHERE tenant_id=? AND usage_day>=? AND usage_day<?",tenant,start,end);monthly=db.update("DELETE FROM invoice_desk_gdt_usage WHERE tenant_id=? AND usage_month=?",tenant,start);}String scope=all?"all":"month";String detail="Usage reset by "+clean(actor,120,"super-admin")+"; scope="+scope+"; monthly="+monthly+"; daily="+daily+"; invoiceCharges="+charges+"; runReservations="+runs;db.update("""
  INSERT INTO invoice_desk_gdt_event(id,tenant_id,company_id,event_type,stage,error_category,http_status,correlation_id,client_version,detail)
  SELECT ?,?,d.company_id,'admin_action',?,'quota_reset',NULL,'','',? FROM invoice_desk_company d WHERE d.tenant_id=? LIMIT 1
  """,UUID.randomUUID(),tenant,"usage_reset_"+scope,sanitize(detail),tenant);return usage(tenant);}

 @Transactional public Usage beginOcr(UUID tenant){Policy p=policy(tenant);active(p);if(!p.onlineOcrEnabled())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Online OCR is disabled for this customer.");db.update("INSERT INTO invoice_desk_gdt_usage(tenant_id,usage_month) VALUES (?,?) ON CONFLICT DO NOTHING",tenant,month());db.update("INSERT INTO invoice_desk_gdt_daily_usage(tenant_id,usage_day) VALUES (?,?) ON CONFLICT DO NOTHING",tenant,today());int monthCount=db.queryForObject("SELECT ocr_attempts FROM invoice_desk_gdt_usage WHERE tenant_id=? AND usage_month=? FOR UPDATE",Integer.class,tenant,month());int dayCount=db.queryForObject("SELECT ocr_attempts FROM invoice_desk_gdt_daily_usage WHERE tenant_id=? AND usage_day=? FOR UPDATE",Integer.class,tenant,today());if(monthCount>=p.monthlyOcrLimit())throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Monthly OCR allowance exhausted.");if(dayCount>=p.dailyOcrLimit())throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Daily OCR allowance exhausted.");db.update("UPDATE invoice_desk_gdt_usage SET ocr_attempts=ocr_attempts+1,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND usage_month=?",tenant,month());db.update("UPDATE invoice_desk_gdt_daily_usage SET ocr_attempts=ocr_attempts+1,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND usage_day=?",tenant,today());return usage(tenant);}
 public void ocrSucceeded(UUID tenant){db.update("UPDATE invoice_desk_gdt_usage SET ocr_successes=ocr_successes+1,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND usage_month=?",tenant,month());}

 public LoginGate loginGate(UUID tenant,String accountHash){String hash=hash(accountHash);var rows=db.query("SELECT consecutive_failures,blocked_until FROM invoice_desk_gdt_login_guard WHERE tenant_id=? AND account_hash=?",(rs,n)->new Object[]{rs.getInt(1),rs.getObject(2,OffsetDateTime.class)},tenant,hash);if(rows.isEmpty())return new LoginGate(true,0,null,"Ready");int failures=(Integer)rows.get(0)[0];OffsetDateTime until=(OffsetDateTime)rows.get(0)[1];Instant blocked=until==null?null:until.toInstant();boolean allowed=blocked==null||!Instant.now().isBefore(blocked);if(allowed&&blocked!=null){db.update("UPDATE invoice_desk_gdt_login_guard SET consecutive_failures=0,blocked_until=NULL WHERE tenant_id=? AND account_hash=?",tenant,hash);failures=0;blocked=null;}return new LoginGate(allowed,failures,blocked,allowed?"Ready":"Too many rejected logins. Try again after "+blocked);}
 @Transactional public LoginGate loginResult(UUID tenant,String accountHash,boolean success,boolean rejected){String hash=hash(accountHash);if(success){db.update("DELETE FROM invoice_desk_gdt_login_guard WHERE tenant_id=? AND account_hash=?",tenant,hash);return new LoginGate(true,0,null,"Login successful");}if(!rejected)return loginGate(tenant,accountHash);db.update("INSERT INTO invoice_desk_gdt_login_guard(tenant_id,account_hash,consecutive_failures) VALUES (?,?,1) ON CONFLICT(tenant_id,account_hash) DO UPDATE SET consecutive_failures=invoice_desk_gdt_login_guard.consecutive_failures+1,updated_at=CURRENT_TIMESTAMP",tenant,hash);int failures=db.queryForObject("SELECT consecutive_failures FROM invoice_desk_gdt_login_guard WHERE tenant_id=? AND account_hash=? FOR UPDATE",Integer.class,tenant,hash);if(failures>=5){db.update("UPDATE invoice_desk_gdt_login_guard SET blocked_until=CURRENT_TIMESTAMP+INTERVAL '10 minutes' WHERE tenant_id=? AND account_hash=?",tenant,hash);return loginGate(tenant,accountHash);}return new LoginGate(true,failures,null,(5-failures)+" login attempts remaining");}

 @Transactional public Reservation reserve(UUID tenant,List<String> hashes){Policy p=policy(tenant);active(p);var unique=hashes==null?List.<String>of():hashes.stream().map(GdtControlService::hash).distinct().toList();db.update("INSERT INTO invoice_desk_gdt_usage(tenant_id,usage_month) VALUES (?,?) ON CONFLICT DO NOTHING",tenant,month());UUID reservation=UUID.randomUUID();if("RUN".equalsIgnoreCase(p.invoiceQuotaMode())){int used=db.queryForObject("SELECT report_runs FROM invoice_desk_gdt_usage WHERE tenant_id=? AND usage_month=? FOR UPDATE",Integer.class,tenant,month());if(used>=p.monthlyRunLimit())throw new ResponseStatusException(HttpStatus.PAYMENT_REQUIRED,"Monthly report-run allowance exhausted.");db.update("INSERT INTO invoice_desk_gdt_run_reservation(id,tenant_id,charged_month,state) VALUES (?,?,?,'RESERVED')",reservation,tenant,month());db.update("UPDATE invoice_desk_gdt_usage SET report_runs=report_runs+1,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND usage_month=?",tenant,month());return new Reservation(reservation,unique.size(),1,0,p.monthlyRunLimit()-used-1);}if(unique.isEmpty())return new Reservation(reservation,0,0,0,usage(tenant).invoiceRemaining());if(unique.size()>p.maxInvoicesPerJob())throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Job exceeds maximum "+p.maxInvoicesPerJob()+" invoices.");int used=db.queryForObject("SELECT invoice_downloads FROM invoice_desk_gdt_usage WHERE tenant_id=? AND usage_month=? FOR UPDATE",Integer.class,tenant,month());int added=0;for(String value:unique)added+=db.update("INSERT INTO invoice_desk_gdt_invoice_charge(tenant_id,invoice_hash,reservation_id,state,charged_month) VALUES (?,?,?,'RESERVED',?) ON CONFLICT(tenant_id,invoice_hash) DO NOTHING",tenant,value,reservation,month());if(used+added>p.monthlyInvoiceLimit())throw new ResponseStatusException(HttpStatus.PAYMENT_REQUIRED,"Invoice allowance insufficient: need "+added+", remaining "+Math.max(0,p.monthlyInvoiceLimit()-used)+".");if(added>0)db.update("UPDATE invoice_desk_gdt_usage SET invoice_downloads=invoice_downloads+?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND usage_month=?",added,tenant,month());return new Reservation(reservation,unique.size(),added,unique.size()-added,p.monthlyInvoiceLimit()-used-added);}
 @Transactional public void finish(UUID tenant,UUID reservationId,List<String> successes){int run=db.queryForObject("SELECT COUNT(*) FROM invoice_desk_gdt_run_reservation WHERE id=? AND tenant_id=?",Integer.class,reservationId,tenant);if(run>0){if(successes!=null&&!successes.isEmpty())db.update("UPDATE invoice_desk_gdt_run_reservation SET state='COMPLETED' WHERE id=? AND tenant_id=?",reservationId,tenant);else{int removed=db.update("DELETE FROM invoice_desk_gdt_run_reservation WHERE id=? AND tenant_id=? AND state='RESERVED'",reservationId,tenant);if(removed>0)db.update("UPDATE invoice_desk_gdt_usage SET report_runs=GREATEST(0,report_runs-1),updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND usage_month=?",tenant,month());}return;}Set<String> ok=new HashSet<>();if(successes!=null)successes.forEach(v->ok.add(hash(v)));for(String value:ok)db.update("UPDATE invoice_desk_gdt_invoice_charge SET state='COMPLETED' WHERE tenant_id=? AND reservation_id=? AND invoice_hash=?",tenant,reservationId,value);int released=db.query("DELETE FROM invoice_desk_gdt_invoice_charge WHERE tenant_id=? AND reservation_id=? AND state='RESERVED' RETURNING invoice_hash",(rs,n)->rs.getString(1),tenant,reservationId).size();if(released>0)db.update("UPDATE invoice_desk_gdt_usage SET invoice_downloads=GREATEST(0,invoice_downloads-?),updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND usage_month=?",released,tenant,month());}

 public void event(InvoiceDeskService.Scope scope,Event request){String type=clean(request==null?null:request.eventType(),40,"failure"),stage=clean(request==null?null:request.stage(),60,"unknown"),category=clean(request==null?null:request.errorCategory(),60,"");String detail=sanitize(request==null?null:request.detail());db.update("INSERT INTO invoice_desk_gdt_event(id,tenant_id,company_id,event_type,stage,error_category,http_status,correlation_id,client_version,detail) VALUES (?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),scope.tenantId(),scope.companyId(),type,stage,category,request==null?null:request.httpStatus(),clean(request==null?null:request.correlationId(),80,""),clean(request==null?null:request.clientVersion(),40,""),detail);int days=defaults().telemetryRetentionDays();db.update("DELETE FROM invoice_desk_gdt_event WHERE created_at<CURRENT_TIMESTAMP-make_interval(days=>?)",days);}
 public record Event(String eventType,String stage,String errorCategory,Integer httpStatus,String correlationId,String clientVersion,String detail){}
 private static String clean(String value,int max,String fallback){String text=value==null?fallback:value.trim();if(text.length()>max)text=text.substring(0,max);return text.replaceAll("[\\p{Cntrl}&&[^\\r\\n\\t]]","");}
 private static String sanitize(String value){String text=clean(value,500,"");text=text.replaceAll("(?i)Bearer\\s+[A-Za-z0-9._-]+","Bearer [redacted]").replaceAll("gdts_[A-Za-z0-9_-]+","[session-redacted]").replaceAll("gdtp_[A-Za-z0-9_-]+","[pairing-redacted]");return text;}
 private static String hash(String value){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Objects.toString(value,"").getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}

 public Defaults defaults(){return db.queryForObject("SELECT trial_days,invoice_quota_mode,monthly_run_limit,monthly_invoice_limit,monthly_ocr_limit,daily_ocr_limit,max_invoices_per_job,max_devices,local_ocr_enabled,online_ocr_enabled,telemetry_retention_days FROM invoice_desk_gdt_defaults WHERE singleton=true",(rs,n)->new Defaults(rs.getInt(1),rs.getString(2),rs.getInt(3),rs.getInt(4),rs.getInt(5),rs.getInt(6),rs.getInt(7),rs.getInt(8),rs.getBoolean(9),rs.getBoolean(10),rs.getInt(11)));}
 public Defaults updateDefaults(Defaults v,String user){if(v==null||v.trialDays()<1||!(Set.of("INVOICE","RUN").contains(Objects.toString(v.invoiceQuotaMode(),"").toUpperCase(Locale.ROOT)))||v.monthlyRunLimit()<0||v.monthlyInvoiceLimit()<0||v.monthlyOcrLimit()<0||v.dailyOcrLimit()<0||v.maxInvoicesPerJob()<1||v.maxDevices()<1||v.telemetryRetentionDays()<1)throw new IllegalArgumentException("Invalid GDT defaults");db.update("UPDATE invoice_desk_gdt_defaults SET trial_days=?,invoice_quota_mode=?,monthly_run_limit=?,monthly_invoice_limit=?,monthly_ocr_limit=?,daily_ocr_limit=?,max_invoices_per_job=?,max_devices=?,local_ocr_enabled=?,online_ocr_enabled=?,telemetry_retention_days=?,updated_at=CURRENT_TIMESTAMP,updated_by=? WHERE singleton=true",v.trialDays(),v.invoiceQuotaMode().toUpperCase(Locale.ROOT),v.monthlyRunLimit(),v.monthlyInvoiceLimit(),v.monthlyOcrLimit(),v.dailyOcrLimit(),v.maxInvoicesPerJob(),v.maxDevices(),v.localOcrEnabled(),v.onlineOcrEnabled(),v.telemetryRetentionDays(),user);return defaults();}
}
